insert into public.capabilities (slug, name, category, summary, lede, includes, question, outcome, queries, sort_order, is_active)
values ('brand-strategy', 'Brand Strategy', 'Brand & Identity', 'The commercial logic underneath the brand — what you sell, to whom, and why it wins.', 'Brand strategy is not a mood. It is the argument for why a company deserves to exist, priced correctly, in a market that already has enough. We build that argument first, because every downstream decision — identity, product, pricing, media — is cheaper and sharper once it exists.', ARRAY['Audience and demand mapping', 'Proposition and value articulation', 'Brand architecture', 'Competitive and category analysis']::text[], 'Why should anyone choose us, and pay what we are worth?', 'A written, agreed strategy that makes the next hundred decisions faster.', ARRAY['what is brand strategy', 'brand strategy agency Amsterdam', 'how to position a brand', 'brand strategy vs marketing strategy']::text[], 0, true)
