values ('performance-marketing', 'Performance Marketing', 'Growth & Demand', 'Paid acquisition that respects the brand and the P&L in equal measure.', 'Performance without brand burns cash; brand without performance starves. We run paid media as one system with your brand — creative that could only be you, targeting that is not lazy, and reporting you can actually act on.', ARRAY['Paid search, social and display', 'Creative testing frameworks', 'Measurement and attribution', 'Budget and bid strategy']::text[], 'Is every pound of media working as hard as it could?', 'Acquisition economics that improve as you scale.', ARRAY['performance marketing agency', 'paid media management', 'PPC agency', 'growth marketing']::text[], 13, true)
