values ('investor-readiness', 'Investor Readiness & Investor Meetings', 'Market & Expansion', 'The narrative, deck and evidence that make a company fundable — and the meetings themselves.', 'Investors buy a story about the future, backed by proof from the present. We shape the equity story, sharpen the deck and pressure-test the numbers so the room leans in for the right reasons — and where it helps, we join the meetings themselves.', ARRAY['Equity story and narrative', 'Pitch deck design and copy', 'Data-room narrative support', 'Rehearsal, Q&A prep and investor meetings']::text[], 'Why is this the company to back, now?', 'A raise narrative that survives due diligence.', ARRAY['investor pitch deck agency', 'how to make a fundable pitch', 'equity story', 'seed round narrative']::text[], 24, true)
on conflict (slug) do update set name = excluded.name, category = excluded.category, summary = excluded.summary, lede = excluded.lede, includes = excluded.includes, question = excluded.question, outcome = excluded.outcome, queries = excluded.queries, sort_order = excluded.sort_order;
