values ('exhibitions', 'Exhibitions', 'Experiences', 'Physical and pop-up spaces that let people encounter the brand as an object, not a screen.', 'An exhibition asks more of a brand than a stand ever does — it has to survive being walked around. We design exhibitions, installations and pop-ups that hold up in three dimensions, from spatial concept through to fabrication and install.', ARRAY['Spatial and exhibition concept', 'Graphic and environmental design', 'Fabrication and production management', 'Install and de-rig']::text[], 'Does the brand still feel like itself in a physical space?', 'A space people photograph without being asked to.', ARRAY['exhibition design agency', 'pop-up store design', 'brand installation design', 'trade show stand design']::text[], 27, true)
on conflict (slug) do update set name = excluded.name, category = excluded.category, summary = excluded.summary, lede = excluded.lede, includes = excluded.includes, question = excluded.question, outcome = excluded.outcome, queries = excluded.queries, sort_order = excluded.sort_order;
insert into public.capabilities (slug, name, category, summary, lede, includes, question, outcome, queries, sort_order, is_active)
values ('workshops', 'Workshops', 'Experiences', 'Practical, small-group sessions that leave a team able to do more of the work themselves.', 'We run working sessions, not lectures — on positioning, naming, creative direction and the brief itself — built around your actual project, not a generic deck. Teams leave with a decision made, not just a framework explained.', ARRAY['Workshop design and facilitation', 'Pre-work and materials', 'Live decision-making sessions', 'Written outputs and next steps']::text[], 'What could this team decide for itself, with the right structure in the room?', 'A decision made, not just a framework explained.', ARRAY['brand strategy workshop', 'creative direction workshop', 'positioning workshop facilitation', 'in-house brand training']::text[], 28, true)
on conflict (slug) do update set name = excluded.name, category = excluded.category, summary = excluded.summary, lede = excluded.lede, includes = excluded.includes, question = excluded.question, outcome = excluded.outcome, queries = excluded.queries, sort_order = excluded.sort_order;
insert into public.capabilities (slug, name, category, summary, lede, includes, question, outcome, queries, sort_order, is_active)
values ('trainings', 'Trainings', 'Experiences', 'Longer-form, in-person training in brand strategy and creative direction — opening 2027.', 'Everything we have learned about brand strategy and creative direction, taught directly, over two days, to a small group. Not a webinar series. Not a certificate. The same thinking we charge clients for, taught in person.', ARRAY['Two-day in-person format', 'Maximum twelve participants', 'Brand Strategy and Creative Direction tracks', 'Amsterdam, plus one further city per year']::text[], 'Can the thinking behind the work be taught, not just delivered?', 'A room of people who can now do more of this themselves.', ARRAY['brand strategy training course', 'creative direction training', 'in person branding workshop 2027', 'Not by Accident trainings']::text[], 29, true)
