-- Projects / Case studies
insert into public.projects (
  title, client, slug, year, industry, location, short_description,
  challenge, insight, strategy, outcome, results, services,
  related_capability_slugs, hero_image_media_id, thumbnail_media_id,
  featured, sort_order, status, published_at
) values (
  'Lavanta', null, 'lavanta', '2024', null, 'London', 'A jewellery brand that was being admired and not bought.',
  'Lavanta came to us three years into existence with a clear problem: strong product, strong following, soft sales.', 'The brand was being admired, not bought — priced like affordable luxury when it was already being worn like an heirloom. The gap was never the product. It was the story people had no permission to tell about owning it.', 'We repositioned the brand around the idea of heirloom at a contemporary price point — not affordable luxury, but the last piece in a category of one — and rebuilt the identity, product and demand system around that single idea.', '+34% conversion in six months, and a waiting list for the new collection.', '+34% conversion in six months, and a waiting list.', ARRAY['Brand Strategy', 'Creative Direction', 'SEO', 'Growth Strategy']::text[],
  ARRAY['brand-strategy', 'creative-direction', 'seo', 'growth-strategy']::text[], (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1675773051474-55c4b7d2cf53?w=1600&h=1000&fit=crop&auto=format'), (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1675773051474-55c4b7d2cf53?w=1200&h=800&fit=crop&auto=format'),
  true, 01, 'published', now()
)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, challenge = excluded.challenge, insight = excluded.insight, strategy = excluded.strategy, outcome = excluded.outcome, results = excluded.results, services = excluded.services, related_capability_slugs = excluded.related_capability_slugs, featured = excluded.featured, sort_order = excluded.sort_order;
insert into public.projects (
  title, client, slug, year, industry, location, short_description,
  challenge, insight, strategy, outcome, results, services,
  related_capability_slugs, hero_image_media_id, thumbnail_media_id,
  featured, sort_order, status, published_at
) values (
  'Studio Marché', null, 'studio-marche', '2025', null, 'Paris', 'A market that needed to feel like it belonged to its neighbourhood.',
  'Studio Marché had been running for four years without ever answering the question most successful markets never ask: what are we, exactly?', 'Not the vendors, not the footfall — the market itself was the brand, and nobody had named it as one thing. Every stall had its own identity. The market had none.', 'We defined a position that made the market itself the brand, not the sum of what was sold there, then built the creative system and campaign that let every vendor sit inside it without losing their own voice.', 'Footfall up 22%, and a market that finally reads as one place.', 'Footfall up 22%, and a market that finally reads as one place.', ARRAY['Brand Strategy', 'Brand Positioning', 'Creative Direction', 'Campaign Strategy']::text[],
  ARRAY['brand-strategy', 'brand-positioning', 'creative-direction', 'campaign-strategy']::text[], (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1759050486852-fdfe2fdc7bea?w=1600&h=1000&fit=crop&auto=format'), (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1759050486852-fdfe2fdc7bea?w=1200&h=800&fit=crop&auto=format'),
  false, 02, 'published', now()
)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, challenge = excluded.challenge, insight = excluded.insight, strategy = excluded.strategy, outcome = excluded.outcome, results = excluded.results, services = excluded.services, related_capability_slugs = excluded.related_capability_slugs, featured = excluded.featured, sort_order = excluded.sort_order;
insert into public.projects (
  title, client, slug, year, industry, location, short_description,
  challenge, insight, strategy, outcome, results, services,
  related_capability_slugs, hero_image_media_id, thumbnail_media_id,
  featured, sort_order, status, published_at
) values (
  'Edde', null, 'edde', '2025', null, 'Berlin', 'A skincare brand built to age alongside its customers.',
  'Most skincare brands are afraid of ageing, and build their entire identity around reversing it. Edde''s customers were not afraid of it, and the brand did not yet reflect that.', 'Visible time was not something to hide from this audience. It was a credential — evidence of a life the product was there to support, not correct.', 'We built an identity and digital system that treated ageing as something to understand rather than reverse, from the language on the packaging to the words used on the product pages.', 'Repeat purchase up 41% among customers over fifty.', 'Repeat purchase up 41% among customers over fifty.', ARRAY['Visual Identity', 'Verbal Identity', 'Website Design & Development', 'UX/UI Design']::text[],
  ARRAY['brand-identity', 'verbal-identity', 'web-design-development', 'ux-ui-design']::text[], (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1617050318658-a9a3175e34cb?w=1600&h=1000&fit=crop&auto=format'), (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1617050318658-a9a3175e34cb?w=1200&h=800&fit=crop&auto=format'),
  false, 03, 'published', now()
)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, challenge = excluded.challenge, insight = excluded.insight, strategy = excluded.strategy, outcome = excluded.outcome, results = excluded.results, services = excluded.services, related_capability_slugs = excluded.related_capability_slugs, featured = excluded.featured, sort_order = excluded.sort_order;
insert into public.projects (
  title, client, slug, year, industry, location, short_description,
  challenge, insight, strategy, outcome, results, services,
  related_capability_slugs, hero_image_media_id, thumbnail_media_id,
  featured, sort_order, status, published_at
) values (
  'Hinterland', null, 'hinterland', '2025', null, 'Melbourne', 'A hospitality group that needed to mean something in three cities at once.',
  'Hinterland operated twelve venues across three cities. It was successful by most measures and unrecognisable as a single brand.', 'The problem was not inconsistency of taste — every venue looked considered on its own. It was the absence of a system that let them all be recognisably one company without being identical.', 'We built a brand architecture and identity system that could flex across formats — restaurant, bar, event space — while remaining unmistakably the same company, then rolled it out across all twelve venues.', 'One brand across twelve venues, three cities, no confusion.', 'One brand across twelve venues, three cities, no confusion.', ARRAY['Brand Strategy', 'Brand Architecture', 'Creative Direction', 'Campaign Strategy']::text[],
  ARRAY['brand-strategy', 'brand-architecture', 'creative-direction', 'campaign-strategy']::text[], (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1771440047944-0b5d792213a9?w=1600&h=1000&fit=crop&auto=format'), (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1771440047944-0b5d792213a9?w=1200&h=800&fit=crop&auto=format'),
  false, 04, 'published', now()
)
