-- Articles / Notes
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'The brief is never the brief', 'the-brief-is-never-the-brief', 'Why the document handed to a creative company at the start of a project almost always describes the symptom, not the problem.', '[{"type":"paragraph","text":"There is a document that exists at the start of every brand project. It is usually twelve pages long. It has a section called ''Background'', a section called ''Objectives'', and a section called ''The Challenge''. It is called a brief."},{"type":"paragraph","text":"It is rarely a brief."},{"type":"paragraph","text":"What most clients hand over at the start of a project is a description of the effect of a problem they have not yet named. The brief says: our conversion rate is low. It says: people don''t understand what we sell. It says: we feel premium but our price point doesn''t reflect it."},{"type":"paragraph","text":"These are symptoms. The brief is a list of symptoms. The actual problem — the one that, if solved, makes all the symptoms go away — is never in the brief, because the client does not know what it is. If they knew, they would have fixed it already."},{"type":"paragraph","text":"This is not a criticism. It is the nature of the work. The brief exists to start a conversation, not to define the answer."},{"type":"paragraph","text":"A creative company that takes a brief literally is usually building the wrong thing. Not because the client is wrong, but because the client cannot see the shape of their own problem. That is what they are paying for."},{"type":"paragraph","text":"The first job of any strategy engagement is to translate the brief into the real question. This is harder than it sounds and takes longer than most clients expect. It is almost never appreciated until it is done."}]'::jsonb,
  (select id from public.article_categories where name = 'Essay'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1661178081018-d1b8e685ef10?w=1200&h=800&fit=crop&auto=format'), 8, 'published', '2026-07-03T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'What packaging actually does', 'what-packaging-actually-does', 'A note on the difference between packaging that looks expensive and packaging that makes a product cost more.', '[{"type":"paragraph","text":"Packaging has a job. Most packaging forgets what the job is."},{"type":"paragraph","text":"The job is not to look expensive. A thing that looks expensive is trying. The job is to make someone feel, at the moment they hold it, that the price they paid was correct. That the price was, in fact, conservative."},{"type":"paragraph","text":"This is a much harder thing to achieve, because it requires the packaging to communicate something true about the product rather than something aspirational about the brand. And most brands do not know something true about their product that is worth communicating. They know what category they are in. They know their USP. They do not know what makes their product genuinely different from the thing beside it on the shelf."},{"type":"paragraph","text":"Good packaging is the visual translation of product truth. When the truth is strong, the packaging can be minimal. When the truth is weak, no amount of embossing or weight of board will save it."}]'::jsonb,
  (select id from public.article_categories where name = 'Notes'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1636014724389-270c4e9c0100?w=1200&h=800&fit=crop&auto=format'), 5, 'published', '2026-06-18T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'Naming is not a creative exercise', 'naming-is-not-a-creative-exercise', 'On the misconception that a good brand name comes from a long list and a vote.', '[{"type":"paragraph","text":"Every naming project starts the same way. The client wants a list. The longer the list, the better. They believe that somewhere inside a list of four hundred names, the right one is hiding."},{"type":"paragraph","text":"It is not."},{"type":"paragraph","text":"A brand name is a bet on a set of values that do not yet exist in the market. It does not describe the company. It does not explain what the company sells. It is the beginning of a reputation, which means it only means something after years of work have made it mean something."},{"type":"paragraph","text":"What this means in practice is that the name almost never matters as much as the client thinks it does, and the process of naming almost always matters more. A naming process that requires everyone in the room to agree is a process designed to produce a mediocre outcome that offends no one."},{"type":"paragraph","text":"The best names come from a decision, not a consensus."}]'::jsonb,
  (select id from public.article_categories where name = 'Essay'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1483366774565-c783b9f70e2c?w=1200&h=800&fit=crop&auto=format'), 6, 'published', '2026-05-02T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'Why growth is a brand problem', 'why-growth-is-a-brand-problem', 'The point at which demand generation and brand strategy become the same discipline.', '[{"type":"paragraph","text":"There is a version of marketing that treats brand and demand as separate budgets with separate goals. Brand is what you spend on awareness. Demand is what you spend on conversion. The two teams meet monthly and disagree about attribution."},{"type":"paragraph","text":"This separation made some sense when media was expensive and brand building required years of patient investment. It makes less sense now, when the same piece of work can build awareness, generate desire and drive a transaction in a single scroll."},{"type":"paragraph","text":"The most commercially effective brands we have worked with do not separate these things. They understand that every touchpoint is simultaneously doing brand work and demand work. The distinction is a legacy of media planning, not a useful description of how people actually decide to buy something."},{"type":"paragraph","text":"Growth is a brand problem because desire is a brand outcome. You do not generate demand for something people do not want. You build wanting first. Growth comes next."}]'::jsonb,
  (select id from public.article_categories where name = 'Essay'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1654481414716-2f4ab5fe0fbe?w=1200&h=800&fit=crop&auto=format'), 7, 'published', '2026-04-14T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'The tyranny of the reference', 'the-tyranny-of-the-reference', 'Why the mood board a client arrives with is usually a description of the last brand that impressed them, not the one they should become.', '[{"type":"paragraph","text":"Every project begins with references. A folder, a board, a link to three companies the client admires. This is meant to be helpful, and sometimes it is. More often it is a quiet act of surrender."},{"type":"paragraph","text":"A reference is a description of a problem someone else already solved. It is the visible outcome of a strategy you cannot see, made for a company you are not. Borrowing the outcome without the strategy is how brands end up looking expensive and meaning nothing."},{"type":"paragraph","text":"The companies worth admiring did not arrive at their look by collecting references. They arrived at it by understanding something true about themselves that no one else could claim. The confidence you are responding to is not aesthetic. It is the confidence of a company that knows exactly what it is."},{"type":"paragraph","text":"So we take the references seriously — not as instructions, but as evidence. What is it, precisely, that you envy here? Nine times out of ten the answer is not the typeface or the palette. It is the certainty. And certainty cannot be referenced. It has to be earned."}]'::jsonb,
  (select id from public.article_categories where name = 'Essay'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1509228468518-180dd4864904?w=1200&h=800&fit=crop&auto=format'), 6, 'published', '2026-04-09T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'Premium is a promise, not a finish', 'premium-is-a-promise-not-a-finish', 'On the difference between a brand that looks costly and a brand that behaves as though it is worth the money.', '[{"type":"paragraph","text":"Clients ask for premium the way they ask for the weather. As if it were a setting. Make it feel more premium — add some black, a serif, a little space."},{"type":"paragraph","text":"But premium is not a finish you apply at the end. It is a promise you keep at every point of contact, most of which have nothing to do with how anything looks. It is the speed of the reply. The quality of the box. The person who answers the phone. The fact that nothing is oversold and nothing disappoints."},{"type":"paragraph","text":"A brand feels expensive when the experience never once contradicts the price. The moment it does — a clumsy checkout, a cheap email, a promise not kept — the spell breaks, and no amount of gold foil will restore it."},{"type":"paragraph","text":"This is inconvenient, because it means premium is not something we can hand over in a deck. It is a standard the whole company has to hold, long after we have gone. Our job is to define that standard precisely enough that it can be defended. Keeping it is the client''s."}]'::jsonb,
  (select id from public.article_categories where name = 'Notes'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?w=1200&h=800&fit=crop&auto=format'), 5, 'published', '2026-03-20T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'In defence of the slow project', 'in-defence-of-the-slow-project', 'Why the best brand work resists the timeline it was sold on, and what that actually costs.', '[{"type":"paragraph","text":"Every good project has a moment where it should slow down and almost never does. It is the moment after the research and before the making, when the honest answer is: we do not yet know what this is."},{"type":"paragraph","text":"The pressure at that point is enormous. There is a timeline. There are people waiting. There is a natural human urge to convert uncertainty into activity, to start producing something so that it at least looks like progress. This is how most projects go quietly wrong — not through bad work, but through work made too early, before the thinking had finished."},{"type":"paragraph","text":"The slow project is not slow because anyone is idle. It is slow because it refuses to make things it cannot yet justify. It holds the uncomfortable open question a few days longer than feels reasonable, because the alternative is to answer it badly and spend the next three months defending the answer."},{"type":"paragraph","text":"We are not romantic about time. Slow is expensive and we know it. But the most expensive thing a company can do is build the wrong brand quickly, then live inside it for a decade."}]'::jsonb,
  (select id from public.article_categories where name = 'Field notes'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1495364141860-b0d03eccd065?w=1200&h=800&fit=crop&auto=format'), 6, 'published', '2026-02-28T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'The audience is not everyone', 'the-audience-is-not-everyone', 'A note on why the instinct to appeal to more people is the surest way to move fewer of them.', '[{"type":"paragraph","text":"The most common note we receive on a piece of strategy is some version of: could this speak to more people? It is asked in good faith and it is almost always wrong."},{"type":"paragraph","text":"A brand that tries to be for everyone is legible to no one. It rounds off every edge that might have made someone choose it, in the hope of offending no one who might have walked past anyway. The result is a brand that is technically acceptable to a large group and genuinely wanted by none of it."},{"type":"paragraph","text":"Wanting is specific. It is the feeling that something was made for you, by people who understood you well enough to leave other people out. That feeling is impossible to manufacture at scale, and it is the only feeling that reliably moves someone from interest to purchase."},{"type":"paragraph","text":"So when we narrow the audience, we are not shrinking the opportunity. We are concentrating it. A brand that a small group cannot live without will always outgrow a brand that a large group can take or leave. Reach is a distribution problem. Desire is a definition problem. Solve the second one first."}]'::jsonb,
  (select id from public.article_categories where name = 'Essay'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?w=1200&h=800&fit=crop&auto=format'), 5, 'published', '2026-02-11T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'A logo is the least of it', 'a-logo-is-the-least-of-it', 'Why the mark everyone argues about is the smallest decision in a brand, and the one that should be made last.', '[{"type":"paragraph","text":"The logo gets the meeting. It gets the revisions, the opinions, the person who was quiet all project suddenly finding their voice. It is the part everyone feels qualified to judge, because it is the part that looks like a decision."},{"type":"paragraph","text":"But a logo is a signature, and a signature only means something because of everything the person has done under it. On its own it is a shape. It acquires meaning through repetition, through the quality of the work it sits beside, through years of a company behaving consistently enough that the shape starts to stand for something."},{"type":"paragraph","text":"This is why we make it late, and quietly. By the time we design the mark, the hard decisions are already made — the position, the voice, the system. The logo just has to sit at the front of all that without contradicting it. When the thinking underneath is strong, almost any competent mark will do. When it is weak, no mark will save it."},{"type":"paragraph","text":"Spend the argument on the strategy. Let the logo be the easy part."}]'::jsonb,
  (select id from public.article_categories where name = 'Notes'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1626785774573-4b799315345d?w=1200&h=800&fit=crop&auto=format'), 5, 'published', '2026-01-22T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'The cost of sounding like everyone', 'the-cost-of-sounding-like-everyone', 'On the strange comfort of the words every company uses, and the price of hiding inside them.', '[{"type":"paragraph","text":"Read enough brand copy and you start to notice it is all the same. Everyone is passionate. Everyone is innovative. Everyone puts the customer at the heart of everything they do. The words are so common they have stopped carrying information — they are noise dressed as meaning."},{"type":"paragraph","text":"Companies reach for these words because they are safe. Nobody was ever fired for calling their company innovative. But safe language has a cost that does not show up on any invoice: it makes you invisible. If you sound like everyone, you are asking to be remembered as no one."},{"type":"paragraph","text":"The alternative is frightening, because it requires saying something specific enough that some people will disagree. A real voice has edges. It leaves things out. It commits to a way of seeing the world that not everyone will share, which is exactly what makes the people who do share it feel found."},{"type":"paragraph","text":"We spend a lot of time deleting the words that could belong to anyone. What is left is usually smaller, plainer and far more yours."}]'::jsonb,
  (select id from public.article_categories where name = 'Essay'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=1200&h=800&fit=crop&auto=format'), 6, 'published', '2026-01-08T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'Consistency is not repetition', 'consistency-is-not-repetition', 'The difference between a brand that feels coherent and one that is merely identical everywhere.', '[{"type":"paragraph","text":"Somewhere along the way, consistency came to mean sameness. Use the logo at this size. This blue, never that one. The same headline treatment on every surface. Guidelines became a list of prohibitions, and the brand became a thing you could break but never build."},{"type":"paragraph","text":"Real consistency is not about repeating the same elements. It is about repeating the same judgement. It is the reason two pieces made by different people, in different formats, years apart, still feel like they came from the same mind. That coherence does not come from locking everything down. It comes from everyone involved understanding what the brand is trying to be, so their thousand small decisions point the same way."},{"type":"paragraph","text":"Rigid brands look consistent in a grid and fall apart in the world, because the world always asks for something the guidelines did not anticipate. Coherent brands flex without losing themselves, because the thing holding them together was never the rules — it was the taste underneath the rules."},{"type":"paragraph","text":"Write down the judgement, not just the measurements."}]'::jsonb,
  (select id from public.article_categories where name = 'Field notes'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1503694978374-8a2fa686963a?w=1200&h=800&fit=crop&auto=format'), 6, 'published', '2025-12-17T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;
insert into public.articles (
  title, slug, excerpt, body, category_id, hero_image_media_id,
  reading_time_minutes, status, published_at
) values (
  'Say the price out loud', 'say-the-price-out-loud', 'Why a brand that is shy about what it costs is usually unsure of what it is worth.', '[{"type":"paragraph","text":"You can tell a lot about a company by how it behaves around its own price. The confident ones state it plainly and move on. The unsure ones bury it, gate it behind a form, surround it with justification, or avoid the subject until the last possible moment."},{"type":"paragraph","text":"Price is the clearest thing a brand ever says about itself. It is a claim about worth, made in public, that the whole experience then has to honour. A company that is nervous about its price is really telling you it is not sure the claim is true — and customers feel that hesitation long before they see a number."},{"type":"paragraph","text":"The work of brand is, in large part, the work of earning the right to a price and then having the nerve to name it. When the position is sharp and the experience is whole, the number stops feeling like a risk and starts feeling like a fact. Nothing signals confidence like a company that will simply tell you what it costs."},{"type":"paragraph","text":"If you cannot say the price out loud, the problem is rarely the price."}]'::jsonb,
  (select id from public.article_categories where name = 'Essay'),
  (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=1200&h=800&fit=crop&auto=format'), 5, 'published', '2025-12-03T00:00:00.000Z'
)
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, body = excluded.body, category_id = excluded.category_id, reading_time_minutes = excluded.reading_time_minutes;

