values ('Sara Okafor', 'Founding Partner, Strategy', 'Sara spent a decade in strategy consulting before concluding that brand and commercial thinking should be one discipline, not two. She built Not by Accident on that premise.', (select id from public.media where bucket = 'external' and storage_path = 'https://images.unsplash.com/photo-1675773051474-55c4b7d2cf53?w=600&h=750&fit=crop&auto=format'), 0, true)
